const items = data?.items || [];
const total = data?.total || 0;
const totalPages = data?.totalPages || 1;

const handleSearch = () => {
  setPage(1);
  setActiveSearch(searchValue);
};

const handleKeyDown = (e: React.KeyboardEvent) => {
  if (e.key === 'Enter') {
    handleSearch();
  }
};

const toggleSelectAll = (checked: boolean) => {
  if (checked) {
    setSelectedRows(items.map((row) => row.id));
  } else {
    setSelectedRows([]);
  }
};

const toggleSelectRow = (id: string, checked: boolean) => {
  if (checked) {
    setSelectedRows((prev) => [...prev, id]);
  } else {
    setSelectedRows((prev) => prev.filter((rowId) => rowId !== id));
  }
};

const handleEdit = (item: Dictionary) => {
  setEditingItem(item);
  setEditDialogOpen(true);
};

const handleDeleteSelected = async () => {
  try {
    await deleteMutation.mutateAsync({ type, ids: selectedRows });
    setSelectedRows([]);
    setDeleteDialogOpen(false);
    toast.success(`${selectedRows.length}개 항목이 삭제되었습니다.`);
  } catch (error) {
    toast.error('삭제 중 오류가 발생했습니다.');
  }
};

const handleDownload = async () => {
  try {
    const blob = await downloadMutation.mutateAsync();
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${type.toLowerCase()}_dictionary.csv`;
    document.body.appendChild(a);
    a.click();
    window.URL.revokeObjectURL(url);
    document.body.removeChild(a);
    toast.success('다운로드가 시작되었습니다.');
  } catch (error) {
    toast.error('다운로드 중 오류가 발생했습니다.');
  }
};

const handleReset = async () => {
  try {
    await resetMutation.mutateAsync(type);
    setResetDialogOpen(false);
    toast.success('사전이 초기화되었습니다.');
  } catch (error) {
    toast.error('초기화 중 오류가 발생했습니다.');
  }
};

// Determine if this is a SYNONYM type to show direction
const isSynonymType = category === 'SYNONYM';
const isSetType = category === 'SET';
const isMapType = category === 'MAP';

